describe("AC-13: dispatch watch — streams line-prefixed output", () => {
  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  it("should print [agent-id session-id] prefix before streamed output", async () => {
    const { PidFileManager } = await import("../src/cli/pid-utils.js");
    vi.spyOn(PidFileManager.prototype, "isDaemonRunning").mockReturnValue(true);
    vi.spyOn(PidFileManager.prototype, "readPort").mockReturnValue(9999);

    const { FakeWs, getLastInstance } = makeFakeWsClass();
    vi.stubGlobal("WebSocket", FakeWs);

    const written: string[] = [];
    vi.spyOn(process.stdout, "write").mockImplementation((chunk) => {
      written.push(String(chunk));
      return true;
    });

    const program = createTestProgram();

    // Start command — will hang on the infinite promise
    const runPromise = program.parseAsync(["agent", "dispatch", "watch"], { from: "user" });

    // Poll until WebSocket is created (initContext() needs several async ticks)
    await waitFor(() => getLastInstance() !== null);

    const ws = getLastInstance();
    expect(ws).not.toBeNull();

    // Simulate connected + subscribed
    ws!.onopen?.({});

    // Send an agent_text_chunk event
    ws!.onmessage?.({
      data: JSON.stringify({
        event: "agent_text_chunk",
        data: {
          session_id: "sess-abc",
          agent_id: "worker",
          text: "hello from agent",
        },
      }),
    });

    await Promise.resolve();

    // AC: @cli-agent-commands ac-13 - output is prefixed with [agent-id session-id]
    const output = written.join("");
    expect(output).toContain("[worker sess-abc]");
    expect(output).toContain("hello from agent");

    // Clean up — the promise never resolves, but that's expected
    runPromise.catch(() => {/* ignore */});
  });

  it("should prefix once per line when text arrives as token-sized chunks", async () => {
    const { PidFileManager } = await import("../src/cli/pid-utils.js");
    vi.spyOn(PidFileManager.prototype, "isDaemonRunning").mockReturnValue(true);
    vi.spyOn(PidFileManager.prototype, "readPort").mockReturnValue(9999);

    const { FakeWs, getLastInstance } = makeFakeWsClass();
    vi.stubGlobal("WebSocket", FakeWs);

    const written: string[] = [];
    vi.spyOn(process.stdout, "write").mockImplementation((chunk) => {
      written.push(String(chunk));
      return true;
    });

    const program = createTestProgram();
    const runPromise = program.parseAsync(["agent", "dispatch", "watch"], { from: "user" });

    await waitFor(() => getLastInstance() !== null);
    const ws = getLastInstance()!;
    ws.onopen?.({});

    // Simulate token-level chunking from one stream (no newlines until later).
    for (const token of ["I", " am", " streaming", "\nNext", " line"]) {
      ws.onmessage?.({
        data: JSON.stringify({
          event: "agent_text_chunk",
          data: {
            session_id: "sess-abc",
            agent_id: "worker",
            text: token,
          },
        }),
      });
    }

    await Promise.resolve();

    const output = written.join("");
    expect(output).toContain("[worker sess-abc] I am streaming");
    expect(output).toContain("\n[worker sess-abc] Next line");
    expect((output.match(/\[worker sess-abc\]/g) ?? []).length).toBe(2);

    runPromise.catch(() => {/* ignore */});
  });

  it("should start a new prefixed line when output switches between streams", async () => {
    const { PidFileManager } = await import("../src/cli/pid-utils.js");
    vi.spyOn(PidFileManager.prototype, "isDaemonRunning").mockReturnValue(true);
    vi.spyOn(PidFileManager.prototype, "readPort").mockReturnValue(9999);

    const { FakeWs, getLastInstance } = makeFakeWsClass();
    vi.stubGlobal("WebSocket", FakeWs);

    const written: string[] = [];
    vi.spyOn(process.stdout, "write").mockImplementation((chunk) => {
      written.push(String(chunk));
      return true;
    });

    const program = createTestProgram();
    const runPromise = program.parseAsync(["agent", "dispatch", "watch"], { from: "user" });

    await waitFor(() => getLastInstance() !== null);
    const ws = getLastInstance()!;
    ws.onopen?.({});

    ws.onmessage?.({
      data: JSON.stringify({
        event: "agent_text_chunk",
        data: { session_id: "sess-a", agent_id: "worker-a", text: "hello" },
      }),
    });
    ws.onmessage?.({
      data: JSON.stringify({
        event: "agent_text_chunk",
        data: { session_id: "sess-b", agent_id: "worker-b", text: "world" },
      }),
    });

    await Promise.resolve();

    const output = written.join("");
    expect(output).toContain("[worker-a sess-a] hello\n[worker-b sess-b] world");

    runPromise.catch(() => {/* ignore */});
  });

  it("should place distinct same-stream messages on separate lines at empty-chunk boundary", async () => {
    const { PidFileManager } = await import("../src/cli/pid-utils.js");
    vi.spyOn(PidFileManager.prototype, "isDaemonRunning").mockReturnValue(true);
    vi.spyOn(PidFileManager.prototype, "readPort").mockReturnValue(9999);

    const { FakeWs, getLastInstance } = makeFakeWsClass();
    vi.stubGlobal("WebSocket", FakeWs);

    const written: string[] = [];
    vi.spyOn(process.stdout, "write").mockImplementation((chunk) => {
      written.push(String(chunk));
      return true;
    });

    const program = createTestProgram();
    const runPromise = program.parseAsync(["agent", "dispatch", "watch"], { from: "user" });

    await waitFor(() => getLastInstance() !== null);
    const ws = getLastInstance()!;
    ws.onopen?.({});

    ws.onmessage?.({
      data: JSON.stringify({
        event: "agent_text_chunk",
        data: { session_id: "sess-abc", agent_id: "worker", text: "First update." },
      }),
    });
    // ACP message boundary sentinel (matches legacy Ralph parser semantics).
    ws.onmessage?.({
      data: JSON.stringify({
        event: "agent_text_chunk",
        data: { session_id: "sess-abc", agent_id: "worker", text: "" },
      }),
    });
    await Promise.resolve();

    ws.onmessage?.({
      data: JSON.stringify({
        event: "agent_text_chunk",
        data: { session_id: "sess-abc", agent_id: "worker", text: "Second update." },
      }),
    });
    await Promise.resolve();

    const output = written.join("");
    expect(output).toContain("[worker sess-abc] First update.\n[worker sess-abc] Second update.");

    runPromise.catch(() => {/* ignore */});
  });

  it("should split at sentence boundary when adapter omits empty-chunk delimiter", async () => {
    const { PidFileManager } = await import("../src/cli/pid-utils.js");
    vi.spyOn(PidFileManager.prototype, "isDaemonRunning").mockReturnValue(true);
    vi.spyOn(PidFileManager.prototype, "readPort").mockReturnValue(9999);

    const { FakeWs, getLastInstance } = makeFakeWsClass();
    vi.stubGlobal("WebSocket", FakeWs);

    const written: string[] = [];
    vi.spyOn(process.stdout, "write").mockImplementation((chunk) => {
      written.push(String(chunk));
      return true;
    });

    const program = createTestProgram();
    const runPromise = program.parseAsync(["agent", "dispatch", "watch"], { from: "user" });

    await waitFor(() => getLastInstance() !== null);
    const ws = getLastInstance()!;
    ws.onopen?.({});

    ws.onmessage?.({
      data: JSON.stringify({
        event: "agent_text_chunk",
        data: { session_id: "sess-abc", agent_id: "worker", text: "for prior implementation." },
      }),
    });
    ws.onmessage?.({
      data: JSON.stringify({
        event: "agent_text_chunk",
        data: { session_id: "sess-abc", agent_id: "worker", text: "I confirmed the task has no linked spec." },
      }),
    });

    await Promise.resolve();

    const output = written.join("");
    expect(output).toContain(
      "[worker sess-abc] for prior implementation.\n[worker sess-abc] I confirmed the task has no linked spec.",
    );

    runPromise.catch(() => {/* ignore */});
  });

  it("should handle empty-first statement boundaries without adding blank lines", async () => {
    const { PidFileManager } = await import("../src/cli/pid-utils.js");
    vi.spyOn(PidFileManager.prototype, "isDaemonRunning").mockReturnValue(true);
    vi.spyOn(PidFileManager.prototype, "readPort").mockReturnValue(9999);

    const { FakeWs, getLastInstance } = makeFakeWsClass();
    vi.stubGlobal("WebSocket", FakeWs);

    const written: string[] = [];
    vi.spyOn(process.stdout, "write").mockImplementation((chunk) => {
      written.push(String(chunk));
      return true;
    });

    const program = createTestProgram();
    const runPromise = program.parseAsync(["agent", "dispatch", "watch"], { from: "user" });

    await waitFor(() => getLastInstance() !== null);
    const ws = getLastInstance()!;
    ws.onopen?.({});

    // Claude ACP often emits empty chunk before a new statement's text stream.
    ws.onmessage?.({
